18	
19	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
20	        String city = owner.getCity();
21	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
22	        String lastName = owner.getLastName();
23	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
24	        long sequence = CheckOwnerCityCapacity.countInCity(ownerRepository, city) + 1;
25	        owner.setCustomerCode(String.format("%s-%s-%04d", city3, last3, sequence));
26	    }
27	}
